from collections import Counter
code='''from collections import Counter

def transform(grid):
    tiles = [[grid[r+i][c:c+5] for i in range(5)]
             for r in range(0, len(grid), 6)
             for c in range(0, len(grid[0]), 6)]
    base = [[Counter(t[i][j] for t in tiles).most_common(1)[0][0]
             for j in range(5)] for i in range(5)]
    changed = {(i, j) for t in tiles for i in range(5) for j in range(5)
               if t[i][j] != base[i][j]}
    return [[1 if (i, j) in changed else base[i][j]
             for j in range(5)] for i in range(5)]
'''
